/* Original micro-lessons and transparent, local research planning helpers. */
(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.REILibraryCore=api})(typeof window!=='undefined'?window:this,()=>{
 const sources={cornell:{title:'Cornell: getting started with library research',url:'https://www.library.cornell.edu/study/introduction-to-research/'},evaluate:{title:'Cornell: critically analyzing information sources',url:'https://guides.library.cornell.edu/critically_analyzing/tips'},purdue:{title:'Purdue OWL: synthesizing sources',url:'https://owl.purdue.edu/owl/research_and_citation/conducting_research/research_overview/synthesizing_sources.html'},review:{title:'Purdue OWL: writing a literature review',url:'https://owl.purdue.edu/owl/research_and_citation/conducting_research/writing_a_literature_review.html'},pubmed:{title:'PubMed: search help',url:'https://pubmed.ncbi.nlm.nih.gov/help/'},ies:{title:'IES: organizing instruction and study',url:'https://ies.ed.gov/ncee/wwc/PracticeGuide/1'},crossref:{title:'Crossref: metadata API',url:'https://www.crossref.org/documentation/retrieve-metadata/rest-api'}};
 const lessons=[
 {id:'question',title:'Rescue a question that is too big',category:'Plan',time:'3–5 min',problem:'“Does technology make education better?” gives you no clear population, technology, outcome or way to answer.',idea:'Choose what you want to understand before choosing a method. Bound the people or materials, setting and phenomenon. A narrower question still needs a worthwhile reason and evidence of the problem.',example:[['Start','Students use learning apps. That is a topic, not evidence that the apps help.'],['Bound it','Focus on first-year students at one campus using one named study app.'],['Match the aim','If you want their experiences, ask how they describe using it to organize study. Do not promise to measure improvement with interviews alone.']],scenario:'You can interview a small group at one campus. Which question best fits those resources?',options:['Does the app cause higher grades for every student?','How do first-year users at this campus describe the app’s role in planning study?'],best:1,why:['A small interview study alone cannot establish a causal grade effect or represent every student.','The question names a bounded group, setting and experience. Selection, consent and analysis still need justification.'],transfer:'Use the question planner to compare possible questions and their evidence needs.',tool:'question',source:['cornell'],lesson:5},
 {id:'search',title:'Turn one topic into a useful search',category:'Find',time:'3–5 min',problem:'Searching a whole research question can hide useful studies that use different words.',idea:'Separate the main concepts. Use OR for alternatives within one concept and AND to connect concepts. Test a small search, inspect relevant records and revise terms. Database syntax and coverage differ.',example:[['Concept 1','commuter, commuting'],['Concept 2','student, undergraduate'],['Combine','(commuter OR commuting) AND (student OR undergraduate). Start broad; add study planning only if the results need narrowing.']],scenario:'You get very few results. Which is a sensible first adjustment?',options:['Add five more concepts with AND','Remove one restrictive concept and inspect alternative terms in relevant papers'],best:1,why:['Extra AND conditions generally narrow a Boolean search further.','A broader search can reveal vocabulary you missed. Record the change, and check whether relevance improves.'],transfer:'The search builder assembles your concept groups and opens an actual database search.',tool:'search',source:['pubmed','cornell'],lesson:2},
 {id:'read',title:'Read a paper for the decision you need',category:'Read',time:'4–6 min',problem:'A title and abstract can sound convincing while hiding selection, measurement and uncertainty.',idea:'First identify the question, study type and participants/materials. Then inspect methods and results relevant to your question. Record the finding separately from the authors’ interpretation, along with a limitation and page/location.',example:[['Finding','Fictional survey: students reporting longer travel also report less study time.'],['Boundary','Self-report and a one-time survey do not establish that travel caused the difference.'],['Useful note','Record population, selection, measures, association and possible confounding. Check the original results before quoting.']],scenario:'Only an abstract is available. What can you responsibly do?',options:['Treat missing method details as confirmed','Use it to screen relevance, mark missing details and seek the full text before making a strong claim'],best:1,why:['An abstract’s silence cannot confirm sampling, measurement or analysis quality.','Screening is useful, but uncertainty must remain visible until you inspect the needed sections.'],transfer:'Find papers, then use the project Reader to keep exact passages separate from your interpretation.',tool:'papers',source:['evaluate'],lesson:3},
 {id:'synthesis',title:'Make two studies talk to each other',category:'Read',time:'4–6 min',problem:'“Study A says X. Study B says Y.” lists findings without explaining their relationship.',idea:'Organize around a question or theme. Compare methods, populations and findings; explain agreement, differences and what remains unresolved. Do not invent a research gap from two papers.',example:[['Study A','Fictional survey: longer travel is associated with less self-reported study time.'],['Study B','Fictional interviews: commuters describe planning around unpredictable delays.'],['Synthesis','The accounts suggest planning is worth examining alongside travel duration. Different methods answer different questions; neither study establishes a universal causal effect.']],scenario:'Different methods produce different findings. What should you inspect first?',options:['Which article has more citations, so it must be right','Whether the studies measure the same thing in comparable settings and populations'],best:1,why:['Citation counts do not settle whether methods or claims are appropriate.','Check comparability before declaring contradiction. Both studies may reveal different aspects of the problem.'],transfer:'Use the project synthesis matrix to compare evidence by your own defined themes.',tool:'projects',source:['purdue','review'],lesson:3},
 {id:'method',title:'Choose evidence before a method label',category:'Plan',time:'4–6 min',problem:'Choosing “survey” because it feels easy can leave your actual question unanswered.',idea:'Ask what evidence would answer the question, whether you can access it, and how it would be analyzed. Different aims need different evidence. Feasibility and ethics can change the question itself.',example:[['Aim','Understand how students experience feedback.'],['Mismatch','A count of submitted assignments records behavior, not their account of feedback.'],['Alignment','Justified participant selection and consent-based interviews may address experience. Explain the analytic approach and limits; do not generalize prevalence from those interviews.']],scenario:'You want to test whether a program caused improvement. Is a one-time satisfaction survey enough?',options:['Yes, positive opinions establish the program’s effect','No; causal evaluation needs an appropriate comparison/design and consideration of alternative explanations'],best:1,why:['Satisfaction may be worth studying, but it is not the same outcome as improvement or a causal comparison.','Clarify the outcome, comparison, timing and threats to inference. If those are infeasible, revise the claim or question.'],transfer:'The planner explains the evidence needs and limitations of different question types.',tool:'question',source:['cornell'],lesson:7},
 {id:'claim',title:'Make a claim your evidence can carry',category:'Write',time:'3–5 min',problem:'A confident sentence can claim more than the study actually supports.',idea:'Name the context and evidence type. Distinguish association, experience and causal effects. State uncertainty without making the paragraph meaningless. An accurate citation cannot fix an unsupported inference.',example:[['Too strong','“Commuting causes poor academic performance.”'],['Bounded','“In this fictional volunteer survey, longer commutes were associated with less self-reported study time.”'],['Next sentence','“Selection, reporting and other differences limit causal interpretation; evidence from other settings is needed.”']],scenario:'A source supports an association. Which revision stays inside that evidence?',options:['Replace “associated with” with “proves” to sound decisive','Name the sampled setting and association, then explain an important limitation'],best:1,why:['Stronger wording does not strengthen the design or rule out alternative explanations.','A useful argument is clear about both what the result contributes and what it cannot establish.'],transfer:'Keep claims linked to supporting or challenging evidence in your project.',tool:'projects',source:['evaluate','purdue'],lesson:8}
 ];
 const clean=x=>String(x??'').replace(/\s+/g,' ').trim().slice(0,180);
 const aims={experience:{label:'Understand experiences',question:(t,g,s)=>`How do ${g} describe their experiences of ${t} within ${s}?`,alternative:(t,g,s)=>`What challenges and enabling factors do ${g} describe in relation to ${t} within ${s}?`,method:'Consider interviews or other suitable qualitative accounts, with justified selection and an explicit analytic approach.',needs:'Access to people with relevant experience, consent, an interview/observation plan and a defensible analysis.',limit:'Accounts can illuminate meaning and context; this alone does not estimate population prevalence or establish cause.'},describe:{label:'Describe a pattern',question:(t,g,s)=>`What patterns of ${t} are observed among ${g} within ${s}?`,alternative:(t,g,s)=>`How does ${t} vary across explicitly defined groups or conditions among ${g} within ${s}?`,method:'Consider structured observations, a descriptive survey or appropriate existing records.',needs:'A clearly defined measure, sampling/selection plan and descriptive analysis with uncertainty.',limit:'Describe only what the selection and measurement support. A convenience sample is not automatically representative.'},association:{label:'Study a relationship',question:(t,g,s)=>`How is ${t} related to [specify a second measurable construct] among ${g} within ${s}?`,alternative:(t,g,s)=>`Does the observed relationship between ${t} and [second construct] vary by [justified contextual factor] among ${g} within ${s}?`,method:'Consider an observational design measuring both constructs, with a justified analysis and confounder strategy.',needs:'Operational definitions for both variables, selection, adequate data and consideration of alternative explanations.',limit:'An observed relationship alone does not establish causation. Replace bracketed placeholders before using the question.'},evaluate:{label:'Evaluate a change',question:(t,g,s)=>`What change in [defined outcome] follows ${t} for ${g} in ${s}, compared with [justified comparison]?`,alternative:(t,g,s)=>`How feasible and acceptable is ${t} for ${g} within ${s}?`,method:'For effects, consider a justified experimental or quasi-experimental comparison. For feasibility, use suitable process measures and participant accounts.',needs:'A defined outcome, baseline/timing, credible comparison where required, access, ethical review and an analysis plan.',limit:'Before/after differences alone may reflect other changes. If a credible effect design is infeasible, ask a feasibility question instead.'}};
 function plan(raw){const topic=clean(raw.topic),group=clean(raw.group),setting=clean(raw.setting),aim=aims[raw.aim];if(!topic||!group||!setting||!aim)throw Error('Add your topic, people/materials, setting and an aim.');return {topic,group,setting,aim:aim.label,questions:[aim.question(topic,group,setting),aim.alternative(topic,group,setting)],method:aim.method,needs:aim.needs,limit:aim.limit,next:['Check published work for the problem and significance.','Confirm access, consent and institutional requirements.','Define your key concepts and what evidence could change your interpretation.']}}
 function terms(value){return [...new Set(String(value??'').split(/[,\n]/).map(x=>clean(x).replace(/["()\[\]\\]/g,'').trim()).filter(Boolean))].slice(0,8)}
 function search(raw){const groups=[terms(raw.one),terms(raw.two),terms(raw.three)].filter(x=>x.length);if(groups.length<2)throw Error('Enter at least two concept groups. Separate alternatives with commas.');const query=groups.map(g=>'('+g.map(t=>'"'+t+'"').join(' OR ')+')').join(' AND ');return {query,broad:groups.slice(0,2).map(g=>'('+g.map(t=>'"'+t+'"').join(' OR ')+')').join(' AND '),pubmed:'https://pubmed.ncbi.nlm.nih.gov/?term='+encodeURIComponent(query),crossref:'https://search.crossref.org/?q='+encodeURIComponent(groups.flat().join(' ')),notes:'PubMed is strongest for biomedical and life-science literature. Crossref searches scholarly metadata across fields; it is not a complete subject database. Adjust syntax for your institution’s databases.'}}
 function records(data){const field=x=>String(x??'').replace(/\s+/g,' ').trim().slice(0,4000),first=x=>Array.isArray(x)?field(x[0]):'';return (Array.isArray(data?.message?.items)?data.message.items:[]).filter(x=>x&&typeof x==='object').slice(0,8).map(x=>({title:first(x.title),authors:(Array.isArray(x.author)?x.author:[]).filter(a=>a&&typeof a==='object').slice(0,200).map(a=>field([a.given,a.family].filter(Boolean).join(' '))).filter(Boolean),year:field(x.published?.['date-parts']?.[0]?.[0]||x.issued?.['date-parts']?.[0]?.[0]||''),doi:clean(x.DOI),venue:first(x['container-title']),type:clean(x.type),url:x.DOI?'https://doi.org/'+encodeURIComponent(clean(x.DOI)):''}))}

 function ris(items){return items.map(x=>['TY  - '+(x.type==='journal-article'?'JOUR':'GEN'),'TI  - '+String(x.title).replace(/\s+/g,' ').trim(),...x.authors.map(a=>'AU  - '+clean(a)),...(x.year?['PY  - '+clean(x.year)]:[]),...(x.doi?['DO  - '+clean(x.doi)]:[]),...(x.venue?['JO  - '+String(x.venue).replace(/\s+/g,' ').trim()]:[]),...(x.url?['UR  - '+clean(x.url)]:[]),'ER  - '].join('\n')).join('\n\n')+'\n'}
 const teaching={
 question:{outcome:'Spot whether a question fits the people, setting and evidence you can access.',rule:'A question is only as useful as the evidence you can realistically collect.',notice:'Compare the aim of the question with what interviews can actually tell you.',visual:{title:'A question with visible boundaries',cells:[['Phenomenon','Using one study app'],['People','First-year users'],['Setting','One campus'],['Evidence needed','Accounts of planning experiences']]},transfer:{prompt:'A campus unit gives you anonymized monthly help-desk counts, but no access to interview students. Which starting question fits those records?',options:['How do monthly request counts vary across the recorded academic year?','How do students feel about the help they received?'],best:0,why:['Counts can describe a time pattern if recording is consistent. Check missing months and what each count means.','Feelings are not directly recorded in service counts. You would need another suitable source or revise the question.']}},
 search:{outcome:'Know when to broaden or narrow a search and explain why.',rule:'OR expands alternatives within a concept; AND requires concepts together.',notice:'Read each parenthesis as one concept, not a collection of unrelated keywords.',visual:{title:'How the search is assembled',cells:[['Alternatives · OR','commuter OR commuting'],['Alternatives · OR','student OR undergraduate'],['Connect · AND','Require both concept groups'],['Revise','Inspect relevant records for terms you missed']]},transfer:{prompt:'Your search returns thousands of broadly relevant records. What would you try next?',options:['Add every word from your proposal title','Add one justified concept or field restriction, then check whether important papers remain'],best:1,why:['A title may contain incidental words that exclude useful records. More words do not automatically make a good strategy.','Narrow one dimension at a time and inspect the trade-off. Record the query and filters so the decision is traceable.']}},
 read:{outcome:'Separate a reported result from an interpretation that the design cannot support.',rule:'Read the method and the result together before deciding what the paper contributes.',notice:'An association and a causal explanation are different claims, even when the topic is identical.',visual:{title:'A source note you can defend',cells:[['Design','One-time volunteer survey'],['Observed result','Travel and reported study time are associated'],['Possible limits','Selection, self-report, other differences'],['Permitted contribution','A pattern to investigate; not a causal conclusion']]},transfer:{prompt:'A study reports a large difference but says one group volunteered and the other did not. What needs attention?',options:['Whether selection could explain some of the difference','Only whether the article has an impressive title'],best:0,why:['Different selection can create group differences unrelated to the proposed explanation. Inspect recruitment, baseline differences and analysis.','The title does not resolve a design issue. Read how groups were selected and what comparisons are justified.']}},
 synthesis:{outcome:'Connect studies through a theme while keeping differences in their evidence visible.',rule:'Synthesis explains relationships; it does not count how many papers agree.',notice:'The methods differ, so the two studies may illuminate different parts of the same question.',visual:{title:'Compare before combining',cells:[['Survey contribution','A reported association in one sample'],['Interview contribution','Accounts of planning around delays'],['Shared theme','Study planning under travel constraints'],['Still uncertain','How the findings transfer to other settings']]},transfer:{prompt:'Two papers report different outcomes, but study different age groups and use different measures. What is the most useful synthesis move?',options:['Average their conclusions into one universal statement','Explain the measurement and population differences before judging agreement'],best:1,why:['Averaging conclusions hides differences that may change what the results mean. It is not a justified meta-analysis.','Those differences may explain the apparent disagreement. Compare the actual results and uncertainty before proposing an explanation.']}},
 method:{outcome:'Choose evidence and analysis that can address the actual research aim.',rule:'Aim → evidence → collection → analysis → claim. Check every connection.',notice:'A convenient measure is not enough if it does not answer the question you asked.',visual:{title:'Keep the alignment visible',cells:[['Aim','Understand feedback experiences'],['Evidence','Relevant participant accounts'],['Analysis','A justified interpretation of those accounts'],['Claim boundary','Experience in context; not prevalence or causation']]},transfer:{prompt:'You can observe queue lengths and service times at a help desk. Which aim best matches this evidence?',options:['Describe variation in waiting and service patterns during the observation periods','Prove that a new staffing policy causes better wellbeing'],best:0,why:['This aim matches the observable measures. Define observation periods, selection and measurement consistency.','Wellbeing and a policy effect require different measures and a defensible comparison; queue observations alone do not establish them.']}},
 claim:{outcome:'Write a useful conclusion without exceeding the design or the sample.',rule:'Keep the contribution clear, then name the boundary that changes its interpretation.',notice:'Watch how the verb changes from a causal assertion to an observed relationship.',visual:{title:'What changes in the claim?',cells:[['Too strong','Commuting causes poor performance'],['What was measured','Travel and self-reported study time'],['Better fit','An association in the sampled responses'],['Boundary','Selection and other differences limit interpretation']]},transfer:{prompt:'You interview volunteers at one campus. Which statement fits what the study can contribute?',options:['These results show what all students need','Participants described these needs in this setting; other groups may differ'],best:1,why:['Volunteer accounts from one setting do not justify a statement about every student.','This preserves a meaningful contribution while showing the setting and selection boundary. Explain the analysis and evidence behind the themes.']}}
 };
 // Vary answer positions so learners must inspect the reasoning rather than a fixed pattern.
 lessons.forEach((x,i)=>{if(i%2===0){x.options.reverse();x.why.reverse();x.best=x.options.length-1-x.best;}});
 return {sources,lessons,teaching,aims,plan,search,records,ris};
});
